import{z as B,x as p,o as t,c as d,q as o,j as i,D as E,d as r,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"锡滴发生器","description":"","frontmatter":{"title":"锡滴发生器","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/droplet-generator.md","filePath":"litho/droplet-generator.md","lastUpdated":1791063341000}'),A={name:"litho/droplet-generator.md"};function h(m,a,D,u,P,C){const l=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="锡滴发生器" tabindex="-1">锡滴发生器 <a class="header-anchor" href="#锡滴发生器" aria-label="Permalink to &quot;锡滴发生器&quot;">​</a></h1><div class="epigraph"><p>预脉冲配方假定每一滴都准时、同位、同质量地走进焦斑；发生器把这件事做成数十 kHz 的流体力学合同。</p><footer>—— 改写自 ASML / Cymer 对 LPP 锡滴发生器的公开叙述</footer></div><p><a href="/litho/euv-prepulse">上一课</a>把转换效率从实心球的约 1% 抬到展开靶的约 5–6%。缺口是：那两枪只对「滴已经在预定时空点」成立——直径约 20–30 μm、重复频率约 50 kHz 量级、位置抖动小于主脉冲焦斑。本课钉锡滴发生器。滴到位之后价态窗口由谁定，留给<a href="/litho/tin-ionization">下一课</a>；碎屑如何打收集镜，是后面<a href="/litho/tin-debris">锡碎屑与防护</a>一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>量产 LPP 不能用烧蚀固体锡盘：靶材不可补充、碎屑谱不可接受。<a href="/litho/euv-lpp-tin">LPP</a> 把每次击打的质量量子化成一滴液锡。发生器必须在真空里连续喷出尺寸均匀的球，并让探测系统在预脉冲到达前锁定轨迹。缺任何一项：主脉冲打空，IF 功率掉，未电离的锡变成最难清的微滴。</p><p>扫描曝光把光子预算摊在狭缝驻留时间上。滴频必须与激光重频对齐，才能在<a href="/litho/euv-power-throughput">剂量</a>合同内攒够带内能量。频率不是越高越好：相邻滴的尾流、氢气流和上一次等离子体残荷会改下一滴的形状与落点。发生器要交的是稳定的时空栅格，不是实验室里的单滴纪录。</p><h3 id="抖动比平均直径更毒" tabindex="-1">抖动比平均直径更毒 <a class="header-anchor" href="#抖动比平均直径更毒" aria-label="Permalink to &quot;抖动比平均直径更毒&quot;">​</a></h3><p>公开叙述里滴径约 20–30 μm，质量纳克级。平均尺寸偏一点，预脉冲展开时间可以重调；逐滴位置与速度抖动会让预脉冲偏心，盘法向歪掉，主脉冲看到侧缘。CE 和离子抛射方向一起漂，剂量环只能加激光能量硬扛，碎屑谱往往更差。伺服对象因此是落点，不是喷嘴上的平均流量。</p><p><span class="marginnote">发生器喷出的是液锡球，不是 13.5 nm 光束。曝光光仍来自主脉冲点燃的 Sn 离子 UTA。不要把「滴频 50 kHz」写成光源的光学调制频率——它是靶的到达率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一条公开链是：储锡与控温 → 喷嘴形成射流或受激液滴链 → 真空中飞行 → 光电探测触发预脉冲与主脉冲 → 未击中或残余锡回收。Cymer 并入 ASML 之后，发生器与 CO₂ MOPA、收集舱写在同一套光源架构里，而不是外挂一台商品喷雾器。</p><p>探测给出到达时刻与横向位置，激光延时按飞行时间外推到相互作用点。氢缓冲在这个时间尺度上近似定常，它不生成滴，但改变阻力和卫星滴的命运。回收与加热回路把未用锡送回，避免腔壁长成金属膜，也避免喷嘴因氧化或冷凝堵死。</p><h3 id="与双脉冲时序锁在同一时钟" tabindex="-1">与双脉冲时序锁在同一时钟 <a class="header-anchor" href="#与双脉冲时序锁在同一时钟" aria-label="Permalink to &quot;与双脉冲时序锁在同一时钟&quot;">​</a></h3><p>50 kHz 量级意味着相邻滴间隔约 20 μs，预脉冲到主脉冲只有数微秒膨胀窗。发生器时钟、滴探测和两束激光必须是同一条触发树。改滴径等于改光学厚度与展开时间，预脉冲能量表要重资格认证，不能把「5–6% CE」当成与发生器无关的常数。</p>',14)),(t(),i(n,null,{default:E(()=>[s(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E9%94%A1%E6%BB%B4%E5%8F%91%E7%94%9F%E5%99%A8%22%5D%20--%3E%20DROP%5B%2220-30%20%CE%BCm%20%E6%B6%B2%E6%BB%B4%E9%93%BE%22%5D%0A%20%20DROP%20--%3E%20DET%5B%22%E6%8E%A2%E6%B5%8B%E8%A7%A6%E5%8F%91%22%5D%0A%20%20DET%20--%3E%20PP%5B%22%E9%A2%84%E8%84%89%E5%86%B2%E5%B1%95%E5%BC%80%22%5D%0A%20%20PP%20--%3E%20MP%5B%22CO%E2%82%82%20%E4%B8%BB%E8%84%89%E5%86%B2%22%5D%0A%20%20MP%20--%3E%20EUV%5B%22%E5%B8%A6%E5%86%85%20EUV%22%5D%0A%20%20DROP%20--%3E%20REC%5B%22%E6%9C%AA%E5%87%BB%E4%B8%AD%E9%94%A1%E5%9B%9E%E6%94%B6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"连续射流在表面张力下断裂成滴；量产需要把断裂做成受控的等间距链，而不是随机卫星滴。卫星滴打在焦斑外，既不出光，又给收集镜送微滴。温度决定黏度与蒸气压：太冷则喷射不稳，太热则蒸发在喷嘴和飞行段上镀锡。真空中没有空气动力稳定翼，横向扰动会一直积分到相互作用点。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：水龙头开成细细一条流，水柱会自己断成一串大致均匀的水珠——表面张力天生爱把液柱切成等间距的球（瑞利断裂）。发生器做的事就是用压电振动「点名」断在哪一刻，把随机滴水变成 50 kHz 的点名签到。")],-1)),(t(),i(n,null,{default:E(()=>[s(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20JIT%5B%22%E9%80%90%E6%BB%B4%E4%BD%8D%E7%BD%AE%2F%E9%80%9F%E5%BA%A6%E6%8A%96%E5%8A%A8%22%5D%20--%3E%20OFF%5B%22%E9%A2%84%E8%84%89%E5%86%B2%E5%81%8F%E5%BF%83%22%5D%0A%20%20OFF%20--%3E%20TILT%5B%22%E5%B1%95%E5%BC%80%E7%9B%98%E6%B3%95%E5%90%91%E6%AD%AA%E6%96%9C%22%5D%0A%20%20TILT%20--%3E%20SIDE%5B%22%E4%B8%BB%E8%84%89%E5%86%B2%E6%89%93%E5%88%B0%E7%9B%98%E4%BE%A7%E7%BC%98%22%5D%0A%20%20SIDE%20--%3E%20CE%5B%22CE%20%E4%B8%8B%E9%99%8D%EF%BC%8CIF%20%E5%8A%9F%E7%8E%87%E6%8E%89%22%5D%0A%20%20SIDE%20--%3E%20ION%5B%22%E7%A6%BB%E5%AD%90%E6%8A%9B%E5%B0%84%E6%96%B9%E5%90%91%E6%BC%82%E7%A7%BB%22%5D%0A%20%20ION%20--%3E%20DEB%5B%22%E7%A2%8E%E5%B1%91%E6%89%93%E4%B8%8A%E6%94%B6%E9%9B%86%E9%95%9C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>命中率直接进平均 IF 功率，也进剂量噪声。扫描狭缝上的瞬时功率抖动变成 CD 抖动；<a href="/litho/euv-stochastics">随机效应</a>要的是剂量绝对值，发生器要的是脉冲间可重复的靶。两者同时坏时，加激光能量往往先把碎屑打猛，再把收集镜寿命吃掉。</p><p><span class="marginnote">常见误区：「没打中的滴只是浪费一点锡」。实际上打空的滴继续飞行撞上腔壁或电极，镀成锡膜；卫星滴飞向收集镜方向。浪费只是账面上最小的一项，碎屑与真空污染才是主要代价。</span></p><p><span class="marginnote">数字实例：50 kHz 滴频意味着相邻滴间隔约 20 μs；若滴速约 80 m/s，滴链在空中的间距约 \\(20\\,\\mu s \\times 80\\,m/s = 1.6\\) mm。预脉冲到主脉冲的几微秒膨胀窗，就发生在下一滴还差约半毫米到一毫米到位的空档里。</span></p><p><span class="marginnote">公开材料给出滴径量级、数十 kHz 重频和「位置必须进焦斑」的稳定性要求，不给出喷嘴孔径与压电波形。后课只引用这条合同，不把会议海报上的实验室喷滴写成厂内配方。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写预脉冲流体力学，也不把磁场碎屑抑制算进发生器。滴频上限受喷嘴寿命、回收热负荷和等离子体残荷限制，不要把「更高 kHz」外推成必然的下一代 CE。后课默认：说到 LPP 靶，先问发生器是否把滴送到预脉冲能展开的时空盒里。</p><p>与固体靶的对比已经在 LPP 课里：发生器换来可补充的量子化靶，代价是真空精密流体力学。国产替代叙事里「会熔锡」远不等于会做这条滴链。引用以 ASML/Cymer 光源公开说明为准。</p><p><span class="marginnote">直径 20–30 μm、约 50 kHz 是公开量级，后续机型公开说过更高重频，但不要写成某一个未证实的 droprate 规格表。本课用「数十 kHz、焦斑尺度抖动」即可。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发生器把锡靶量子化成约 20–30 μm 的液滴链，重频约 50 kHz 量级。</li><li>预脉冲 CE 合同以滴的时空到位为前提；抖动比平均直径更伤。</li><li>探测触发把滴、预脉冲、主脉冲锁在同一时钟上。</li><li>卫星滴与打空脉冲既掉 IF 功率，又恶化碎屑谱。</li><li>下一课从这滴打完之后的电离态写起；中性原子与微滴是碎屑课的账。</li><li>出处：ASML / Cymer LPP 锡滴发生器公开材料。</li></ul>',10))])}const k=B(A,[["render",h]]);export{c as __pageData,k as default};
